pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 unlockTime, uint256 warpDelta, address actor) public {
        vm.assume(actor != address(0));
        uint256 t = bound(warpDelta, 1, 10000 days);
        vm.warp(t);
        uint256 amount = 0;
        vm.deal(actor, amount + 1 wei);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 unlockTimeStored, ) = c.Acc(actor);
        assertTrue(unlockTimeStored >= block.timestamp);
    }
}
